\[DE = \sqrt{16 - x^2} + \sqrt{25 - y^2} + \sqrt{36 - z^2}.\][asy]
unitsize(0.4 cm);

pair A, B, C, D, E, P, Q, R, trans;

A = (0,0);
B = 4*dir(40);
C = B + 5*dir(60);
D = C + 6*dir(30);
E = (D.x,0);
P = (B.x,0);
Q = (C.x,B.y);
R = (D.x,C.y);
trans = (14,0);

draw(A--B--P--cycle);
draw(B--C--Q--cycle);
draw(C--D--R--cycle);
draw(P--E--R,dashed);

